6	-----------------------------------------------------------------------------*/
7	
8	/* -----------------------------------------------------------
9	  Definition of page queues for each block size
10	----------------------------------------------------------- */
11	
12	#ifndef MI_IN_PAGE_C
13	#error "this file should be included from 'page.c'"
14	// include to help an IDE
15	#include "mimalloc.h"
16	#include "mimalloc/internal.h"
17	#include "mimalloc/atomic.h"
18	#endif
19	
20	/* -----------------------------------------------------------
21	  Minimal alignment in machine words (i.e. `sizeof(void*)`)
22	----------------------------------------------------------- */
23	
24	#if (MI_MAX_ALIGN_SIZE > 4*MI_INTPTR_SIZE)
25	  #error "define alignment for more than 4x word size for this platform"
26	#elif (MI_MAX_ALIGN_SIZE > 2*MI_INTPTR_SIZE)
27	  #define MI_ALIGN4W   // 4 machine words minimal alignment
28	#elif (MI_MAX_ALIGN_SIZE > MI_INTPTR_SIZE)
29	  #define MI_ALIGN2W   // 2 machine words minimal alignment
30	#else
31	  // ok, default alignment is 1 word
32	#endif
33	
34	
35	/* -----------------------------------------------------------
36	  Queue query
37	----------------------------------------------------------- */
38	
39	
40	static inline bool mi_page_queue_is_huge(const mi_page_queue_t* pq) {
41	  return (pq->block_size == (MI_LARGE_MAX_OBJ_SIZE+sizeof(uintptr_t)));
42	}
43	
44	static inline bool mi_page_queue_is_full(const mi_page_queue_t* pq) {
45	  return (pq->block_size == (MI_LARGE_MAX_OBJ_SIZE+(2*sizeof(uintptr_t))));
46	}
47	
48	static inline bool mi_page_queue_is_special(const mi_page_queue_t* pq) {
49	  return (pq->block_size > MI_LARGE_MAX_OBJ_SIZE);
50	}
51	
52	static inline size_t mi_page_queue_count(const mi_page_queue_t* pq) {
53	  return pq->count;
54	}
55	
56	/* -----------------------------------------------------------
57	  Bins
58	----------------------------------------------------------- */
59	
60	// Return the bin for a given field size.
61	// Returns MI_BIN_HUGE if the size is too large.
62	// We use `wsize` for the size in "machine word sizes",
63	// i.e. byte size == `wsize*sizeof(void*)`.
64	static size_t mi_bin(size_t size) {
65	  size_t wsize = _mi_wsize_from_size(size);
66	#if defined(MI_ALIGN4W)
67	  if mi_likely(wsize <= 4) {
68	    return (wsize <= 1 ? 1 : (wsize+1)&~1); // round to double word sizes
69	  }
70	#elif defined(MI_ALIGN2W)
71	  if mi_likely(wsize <= 8) {
72	    return (wsize <= 1 ? 1 : (wsize+1)&~1); // round to double word sizes
73	  }
74	#else
75	  if mi_likely(wsize <= 8) {
76	    return (wsize == 0 ? 1 : wsize);
77	  }
78	#endif
79	  else if mi_unlikely(wsize > MI_LARGE_MAX_OBJ_WSIZE) {
80	    return MI_BIN_HUGE;
81	  }
82	  else {
83	    #if defined(MI_ALIGN4W)
84	    if (wsize <= 16) { wsize = (wsize+3)&~3; } // round to 4x word sizes
85	    #endif
86	    wsize--;
87	    // find the highest bit
88	    const size_t b = (MI_SIZE_BITS - 1 - mi_clz(wsize));  // note: wsize != 0
89	    // and use the top 3 bits to determine the bin (~12.5% worst internal fragmentation).
90	    // - adjust with 3 because we use do not round the first 8 sizes
91	    //   which each get an exact bin
92	    const size_t bin = ((b << 2) + ((wsize >> (b - 2)) & 0x03)) - 3;
93	    mi_assert_internal(bin > 0 && bin < MI_BIN_HUGE);
94	    return bin;
95	  }
96	}
97	
98	
99	
100	/* -----------------------------------------------------------
101	  Queue of pages with free blocks
102	----------------------------------------------------------- */
103	
104	size_t _mi_bin(size_t size) {
105	  return mi_bin(size);
106	}
107	
108	size_t _mi_bin_size(size_t bin) {
109	  mi_assert_internal(bin <= MI_BIN_HUGE);
110	  return _mi_theap_empty.pages[bin].block_size;
111	}
112	
113	// Good size for allocation
114	mi_decl_nodiscard mi_decl_export size_t mi_good_size(size_t size) mi_attr_noexcept {
115	  if (size <= MI_LARGE_MAX_OBJ_SIZE - MI_PADDING_SIZE) {
116	    return _mi_bin_size(mi_bin(size + MI_PADDING_SIZE));
117	  }
118	  else if (size <= MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE) {
119	    return _mi_align_up(size + MI_PADDING_SIZE,_mi_os_page_size());
120	  }
121	  else {
122	    return size;
123	  }
124	}
125	
126	#if (MI_DEBUG>1)
127	static bool mi_page_queue_contains(mi_page_queue_t* queue, const mi_page_t* page) {
128	  mi_assert_internal(page != NULL);
129	  mi_page_t* list = queue->first;
130	  while (list != NULL) {
131	    mi_assert_internal(list->next == NULL || list->next->prev == list);
132	    mi_assert_internal(list->prev == NULL || list->prev->next == list);
133	    if (list == page) break;
134	    list = list->next;
135	  }
136	  return (list == page);
137	}
138	
139	#endif
140	
141	#if (MI_DEBUG>1)
142	static bool mi_theap_contains_queue(const mi_theap_t* theap, const mi_page_queue_t* pq) {
143	  return (pq >= &theap->pages[0] && pq <= &theap->pages[MI_BIN_FULL]);
144	}
145	#endif
146	
147	bool _mi_page_queue_is_valid(mi_theap_t* theap, const mi_page_queue_t* pq) {
148	  MI_UNUSED_RELEASE(theap);
149	  if (pq==NULL) return false;
150	  size_t count = 0; MI_UNUSED_RELEASE(count);
151	  mi_page_t* prev = NULL; MI_UNUSED_RELEASE(prev);
152	  for (mi_page_t* page = pq->first; page != NULL; page = page->next) {
153	    mi_assert_internal(page->prev == prev);
154	    if (mi_page_is_in_full(page)) {
155	      mi_assert_internal(_mi_wsize_from_size(pq->block_size) == MI_LARGE_MAX_OBJ_WSIZE + 2);
156	    }
157	    else if (mi_page_is_huge(page)) {
158	      mi_assert_internal(_mi_wsize_from_size(pq->block_size) == MI_LARGE_MAX_OBJ_WSIZE + 1);
159	    }
160	    else {
161	      mi_assert_internal(mi_page_block_size(page) == pq->block_size);
162	    }
163	    mi_assert_internal(page->theap == theap);
164	    if (page->next == NULL) {
165	      mi_assert_internal(pq->last == page);
166	    }
167	    count++;
168	    prev = page;
169	  }
170	  mi_assert_internal(pq->count == count);
171	  return true;
172	}
173	
174	static size_t mi_page_bin(const mi_page_t* page) {
175	  const size_t bin = (mi_page_is_in_full(page) ? MI_BIN_FULL : (mi_page_is_huge(page) ? MI_BIN_HUGE : mi_bin(mi_page_block_size(page))));
176	  mi_assert_internal(bin <= MI_BIN_FULL);
177	  return bin;
178	}
179	
180	// returns the page bin without using MI_BIN_FULL for statistics
181	size_t _mi_page_stats_bin(const mi_page_t* page) {
182	  const size_t bin = (mi_page_is_huge(page) ? MI_BIN_HUGE : mi_bin(mi_page_block_size(page)));
183	  mi_assert_internal(bin <= MI_BIN_HUGE);
184	  return bin;
185	}
186	
187	static mi_page_queue_t* mi_theap_page_queue_of(mi_theap_t* theap, const mi_page_t* page) {
188	  mi_assert_internal(theap!=NULL);
189	  const size_t bin = mi_page_bin(page);
190	  mi_page_queue_t* pq = &theap->pages[bin];
191	  mi_assert_internal((mi_page_block_size(page) == pq->block_size) ||
192	                       (mi_page_is_huge(page) && mi_page_queue_is_huge(pq)) ||
193	                         (mi_page_is_in_full(page) && mi_page_queue_is_full(pq)));
194	  return pq;
195	}
196	
197	static mi_page_queue_t* mi_page_queue_of(const mi_page_t* page) {
198	  mi_theap_t* theap = mi_page_theap(page);
199	  mi_page_queue_t* pq = mi_theap_page_queue_of(theap, page);
200	  mi_assert_expensive(mi_page_queue_contains(pq, page));
201	  return pq;
202	}
203	
204	// The current small page array is for efficiency and for each
205	// small size (up to 256) it points directly to the page for that
206	// size without having to compute the bin. This means when the
207	// current free page queue is updated for a small bin, we need to update a
208	// range of entries in `_mi_page_small_free`.
209	static inline void mi_theap_queue_first_update(mi_theap_t* theap, const mi_page_queue_t* pq) {
210	  mi_assert_internal(mi_theap_contains_queue(theap,pq));
211	  const size_t size = pq->block_size;
212	  if (size > MI_SMALL_SIZE_MAX) return;
213	
214	  mi_page_t* page = pq->first;
215	  if (pq->first == NULL) page = _mi_page_empty_get();
216	
217	  // find index in the right direct page array
218	  const size_t idx = _mi_wsize_from_size(size);
219	  mi_page_t** const pages_free = theap->pages_free_direct;
220	  if (pages_free[idx] == page) return;  // already set
221	
222	  // find start slot
223	  size_t start;
224	  if (idx<=1) {
225	    start = 0;
226	  }
227	  else {
228	    // find previous size; due to minimal alignment upto 3 previous bins may need to be skipped
229	    mi_assert_internal(pq > &theap->pages[0]); // since idx > 1    
230	    size_t bin = mi_bin(size);
231	    const mi_page_queue_t* prev = pq - 1;
232	    while( bin == mi_bin(prev->block_size) && prev > &theap->pages[0]) {
233	      prev--;
234	    }
235	    start = 1 + _mi_wsize_from_size(prev->block_size);
236	    if (start > idx) start = idx;
237	  }
238	
239	  // set size range to the right page
240	  mi_assert(start <= idx);
241	  for (size_t sz = start; sz <= idx; sz++) {
242	    pages_free[sz] = page;
243	  }
244	}
245	
246	/*
247	static bool mi_page_queue_is_empty(mi_page_queue_t* queue) {
248	  return (queue->first == NULL);
249	}
250	*/
251	
252	static void mi_page_queue_remove(mi_page_queue_t* queue, mi_page_t* page) {
253	  mi_assert_internal(page != NULL);
254	  mi_assert_expensive(mi_page_queue_contains(queue, page));
255	  mi_assert_internal(queue->count >= 1);
256	  mi_assert_internal(mi_page_block_size(page) == queue->block_size ||
257	                      (mi_page_is_huge(page) && mi_page_queue_is_huge(queue)) ||
258	                        (mi_page_is_in_full(page) && mi_page_queue_is_full(queue)));
259	  mi_theap_t* theap = mi_page_theap(page);
260	  if (page->prev != NULL) page->prev->next = page->next;
261	  if (page->next != NULL) page->next->prev = page->prev;
262	  if (page == queue->last)  queue->last = page->prev;
263	  if (page == queue->first) {
264	    queue->first = page->next;
265	    // update first
266	    mi_assert_internal(mi_theap_contains_queue(theap, queue));
267	    mi_theap_queue_first_update(theap,queue);
268	  }
269	  theap->page_count--;
270	  queue->count--;
271	  page->next = NULL;
272	  page->prev = NULL;
273	  mi_page_set_in_full(page,false);
274	}
275	
276	
277	static void mi_page_queue_push(mi_theap_t* theap, mi_page_queue_t* queue, mi_page_t* page) {
278	  mi_assert_internal(mi_page_theap(page) == theap);
279	  mi_assert_internal(!mi_page_queue_contains(queue, page));
280	  #if MI_HUGE_PAGE_ABANDON
281	  mi_assert_internal(_mi_page_segment(page)->page_kind != MI_PAGE_HUGE);
282	  #endif
283	  mi_assert_internal(mi_page_block_size(page) == queue->block_size ||
284	                      (mi_page_is_huge(page) && mi_page_queue_is_huge(queue)) ||
285	                        (mi_page_is_in_full(page) && mi_page_queue_is_full(queue)));
286	
287	  mi_page_set_in_full(page, mi_page_queue_is_full(queue));
288	
289	  page->next = queue->first;
290	  page->prev = NULL;
291	  if (queue->first != NULL) {
292	    mi_assert_internal(queue->first->prev == NULL);
293	    queue->first->prev = page;
294	    queue->first = page;
295	  }
296	  else {
297	    queue->first = queue->last = page;
298	  }
299	  queue->count++;
300	
301	  // update direct
302	  mi_theap_queue_first_update(theap, queue);
303	  theap->page_count++;
304	}
305	
306	static void mi_page_queue_push_at_end(mi_theap_t* theap, mi_page_queue_t* queue, mi_page_t* page) {
307	  mi_assert_internal(mi_page_theap(page) == theap);
308	  mi_assert_internal(!mi_page_queue_contains(queue, page));
309	
310	  mi_assert_internal(mi_page_block_size(page) == queue->block_size ||
311	                      (mi_page_is_huge(page) && mi_page_queue_is_huge(queue)) ||
312	                       (mi_page_is_in_full(page) && mi_page_queue_is_full(queue)));
313	
314	  mi_page_set_in_full(page, mi_page_queue_is_full(queue));
315	
316	  page->prev = queue->last;
317	  page->next = NULL;
318	  if (queue->last != NULL) {
319	    mi_assert_internal(queue->last->next == NULL);
320	    queue->last->next = page;
321	    queue->last = page;
322	  }
323	  else {
324	    queue->first = queue->last = page;
325	  }
326	  queue->count++;
327	
328	  // update direct
329	  if (queue->first == page) {
330	    mi_theap_queue_first_update(theap, queue);
331	  }
332	  theap->page_count++;
333	}
334	
335	static void mi_page_queue_move_to_front(mi_theap_t* theap, mi_page_queue_t* queue, mi_page_t* page) {
336	  mi_assert_internal(mi_page_theap(page) == theap);
337	  mi_assert_internal(mi_page_queue_contains(queue, page));
338	  if (queue->first == page) return;
339	  mi_page_queue_remove(queue, page);
340	  mi_page_queue_push(theap, queue, page);
341	  mi_assert_internal(queue->first == page);
342	}
343	
344	static void mi_page_queue_enqueue_from_ex(mi_page_queue_t* to, mi_page_queue_t* from, bool enqueue_at_end, mi_page_t* page) {
345	  mi_assert_internal(page != NULL);
346	  mi_assert_internal(from->count >= 1);
347	  mi_assert_expensive(mi_page_queue_contains(from, page));
348	  mi_assert_expensive(!mi_page_queue_contains(to, page));
349	  const size_t bsize = mi_page_block_size(page);
350	  MI_UNUSED(bsize);
351	  mi_assert_internal((bsize == to->block_size && bsize == from->block_size) ||
352	                     (bsize == to->block_size && mi_page_queue_is_full(from)) ||
353	                     (bsize == from->block_size && mi_page_queue_is_full(to)) ||
354	                     (mi_page_is_huge(page) && mi_page_queue_is_huge(to)) ||
355	                     (mi_page_is_huge(page) && mi_page_queue_is_full(to)));
356	
357	  mi_theap_t* theap = mi_page_theap(page);
358	
359	  // delete from `from`
360	  if (page->prev != NULL) page->prev->next = page->next;
361	  if (page->next != NULL) page->next->prev = page->prev;
362	  if (page == from->last)  from->last = page->prev;
363	  if (page == from->first) {
364	    from->first = page->next;
365	    // update first
366	    mi_assert_internal(mi_theap_contains_queue(theap, from));
367	    mi_theap_queue_first_update(theap, from);
368	  }
369	  from->count--;
370	
371	  // insert into `to`
372	  to->count++;
373	  if (enqueue_at_end) {
374	    // enqueue at the end
375	    page->prev = to->last;
376	    page->next = NULL;
377	    if (to->last != NULL) {
378	      mi_assert_internal(theap == mi_page_theap(to->last));
379	      to->last->next = page;
380	      to->last = page;
381	    }
382	    else {
383	      to->first = page;
384	      to->last = page;
385	      mi_theap_queue_first_update(theap, to);
386	    }
387	  }
388	  else {
389	    if (to->first != NULL) {
390	      // enqueue at 2nd place
391	      mi_assert_internal(theap == mi_page_theap(to->first));
392	      mi_page_t* next = to->first->next;
393	      page->prev = to->first;
394	      page->next = next;
395	      to->first->next = page;
396	      if (next != NULL) {
397	        next->prev = page;
398	      }
399	      else {
400	        to->last = page;
401	      }
402	    }
403	    else {
404	      // enqueue at the head (singleton list)
405	      page->prev = NULL;
406	      page->next = NULL;
407	      to->first = page;
408	      to->last = page;
409	      mi_theap_queue_first_update(theap, to);
410	    }
411	  }
412	
413	  mi_page_set_in_full(page, mi_page_queue_is_full(to));
414	}
415	
416	static void mi_page_queue_enqueue_from(mi_page_queue_t* to, mi_page_queue_t* from, mi_page_t* page) {
417	  mi_page_queue_enqueue_from_ex(to, from, true /* enqueue at the end */, page);
418	}
419	
420	static void mi_page_queue_enqueue_from_full(mi_page_queue_t* to, mi_page_queue_t* from, mi_page_t* page) {
421	  // note: we could insert at the front to increase reuse, but it slows down certain benchmarks (like `alloc-test`)
422	  mi_page_queue_enqueue_from_ex(to, from, true /* enqueue at the end of the `to` queue? */, page);
423	}
