497	
498	// Is `x` a power of two? (0 is considered a power of two)
499	static inline bool _mi_is_power_of_two(uintptr_t x) {
500	  return ((x & (x - 1)) == 0);
501	}
502	
503	// valid alignment values are as posix memalign: <https://en.cppreference.com/c/memory/aligned_alloc#Notes>
504	static inline bool mi_alignment_is_valid(size_t alignment) {
505	  return ((alignment!=0) && _mi_is_power_of_two(alignment));
506	}
507	
508	// Is a pointer aligned?
509	static inline bool _mi_is_aligned(const void* p, size_t alignment) {
510	  return (alignment==0 || ((uintptr_t)p % alignment) == 0);
511	}
512	
513	// Align upwards
514	static inline uintptr_t _mi_align_up(uintptr_t sz, size_t alignment) {
515	  mi_assert_internal(alignment != 0);
516	  const uintptr_t mask = alignment - 1;
517	  if ((alignment & mask) == 0) {  // power of two?
518	    return ((sz + mask) & ~mask);
519	  }
520	  else {
521	    return (((sz + mask)/alignment)*alignment);
522	  }
523	}
524	
525	// Align a pointer upwards
526	static inline void* _mi_align_up_ptr(const void* p, size_t alignment) {
527	  return (void*)_mi_align_up((uintptr_t)p, alignment);
528	}
529	
530	// Align down
531	static inline uintptr_t _mi_align_down(uintptr_t sz, size_t alignment) {
532	  mi_assert_internal(alignment != 0);
533	  const uintptr_t mask = alignment - 1;
534	  if ((alignment & mask) == 0) {  // power of two?
535	    return (sz & ~mask);
536	  }
537	  else {
538	    return ((sz/alignment)*alignment);
539	  }
540	}
541	
542	// Align a pointer downwards
543	static inline void* _mi_align_down_ptr(const void* p, size_t alignment) {
544	  return (void*)_mi_align_down((uintptr_t)p, alignment);
545	}
546	
547	// Divide upwards: `s <= _mi_divide_up(s,d)*d < s+d`.
548	static inline uintptr_t _mi_divide_up(uintptr_t size, size_t divider) {
549	  mi_assert_internal(divider != 0);
550	  return (divider == 0 ? size : ((size + divider - 1) / divider));
551	}
552	
553	
554	// clamp an integer
555	static inline size_t _mi_clamp(size_t sz, size_t min, size_t max) {
556	  if (sz < min) return min;
557	  else if (sz > max) return max;
558	  else return sz;
559	}
560	
561	// Is memory zero initialized?
562	static inline bool mi_mem_is_zero(const void* p, size_t size) {
563	  for (size_t i = 0; i < size; i++) {
564	    if (((uint8_t*)p)[i] != 0) return false;
565	  }
566	  return true;
567	}
568	
569	// Align a byte size to a size in _machine words_,
570	// i.e. byte size == `wsize*sizeof(void*)`.
571	static inline size_t _mi_wsize_from_size(size_t size) {
572	  mi_assert_internal(size <= SIZE_MAX - sizeof(uintptr_t));
573	  return (size + sizeof(uintptr_t) - 1) / sizeof(uintptr_t);
574	}
575	
576	// Overflow detecting multiply
577	#if __has_builtin(__builtin_umul_overflow) || (defined(__GNUC__) && (__GNUC__ >= 5))
578	#include <limits.h>      // UINT_MAX, ULONG_MAX
579	#if defined(_CLOCK_T)    // for Illumos
580	#undef _CLOCK_T
581	#endif
582	static inline bool mi_mul_overflow(size_t count, size_t size, size_t* total) {
583	  #if (SIZE_MAX == UINT_MAX)
584	    return __builtin_umul_overflow(count, size, (unsigned int *)total);
585	  #elif (SIZE_MAX == ULONG_MAX)
586	    return __builtin_umull_overflow(count, size, (unsigned long *)total);
587	  #else
588	    return __builtin_umulll_overflow(count, size, (unsigned long long *)total);
589	  #endif
590	}
591	#else /* __builtin_umul_overflow is unavailable */
592	static inline bool mi_mul_overflow(size_t count, size_t size, size_t* total) {
593	  *total = count*size;
594	  if mi_likely(((size|count)>>(4*MI_SIZE_SIZE))==0) {  // did size and count fit both in the lower half bits of a size_t?
595	    return false;
596	  }
597	  else {
598	    return (size!=0 && (SIZE_MAX / size) < count);
599	  }
600	}
601	#endif
602	
603	// Safe multiply `count*size` into `total`; return `true` on overflow.
604	static inline bool mi_count_size_overflow(size_t count, size_t size, size_t* total) {
605	  if (count==1) {  // quick check for the case where count is one (common for C++ allocators)
606	    *total = size;
607	    return false;
608	  }
609	  else if mi_likely(!mi_mul_overflow(count, size, total)) {
610	    return false;
611	  }
612	  else {
613	    #if MI_DEBUG > 0
614	    _mi_error_message(EOVERFLOW, "allocation request is too large (%zu * %zu bytes)\n", count, size);
615	    #endif
616	    *total = SIZE_MAX;
617	    return true;
618	  }
619	}
