666	/* -----------------------------------------------------------
667	  The page map maps addresses to `mi_page_t` pointers
668	----------------------------------------------------------- */
669	
670	#if MI_PAGE_MAP_FLAT
671	
672	// flat page-map committed on demand, using one byte per slice (64 KiB).
673	// single indirection and low commit, but large initial virtual reserve (4 GiB with 48 bit virtual addresses)
674	// used by default on <= 40 bit virtual address spaces.
675	extern mi_decl_hidden _Atomic(uint8_t*) _mi_page_map;
676	extern mi_decl_hidden _Atomic(void*)    _mi_page_map_max_address;
677	
678	static inline size_t _mi_page_map_index(const void* p) {
679	  return (size_t)((uintptr_t)p >> MI_ARENA_SLICE_SHIFT);
680	}
681	
682	static inline uint8_t _mi_page_map_at(size_t idx) {
683	  return mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map)[idx];
684	}
685	
686	static inline mi_page_t* _mi_ptr_page_ex(const void* p, bool* valid) {
687	  const size_t idx = _mi_page_map_index(p);
688	  const size_t ofs = _mi_page_map_at(idx);
689	  if (valid != NULL) { *valid = (ofs != 0); }
690	  return (mi_page_t*)((((uintptr_t)p >> MI_ARENA_SLICE_SHIFT) + 1 - ofs) << MI_ARENA_SLICE_SHIFT);
691	}
692	
693	static inline mi_page_t* _mi_checked_ptr_page(const void* p) {
694	  #if MI_MIN_VABITS < MI_INTPTR_BITS
695	  if mi_unlikely(((uintptr_t)p >> MI_MIN_VABITS) != 0) {
696	    if (p > mi_atomic_load_ptr_relaxed(void, &_mi_page_map_max_address)) return NULL;
697	  }
698	  #endif
699	  bool valid;
700	  mi_page_t* const page = _mi_ptr_page_ex(p, &valid);
701	  return (valid ? page : NULL);
702	}
703	
704	static inline mi_page_t* _mi_unchecked_ptr_page(const void* p) {
705	  return _mi_ptr_page_ex(p, NULL);
706	}
707	
708	#else
709	
710	// 2-level page map:
711	// double indirection, but low commit and low virtual reserve.
712	//
713	// the page-map is usually 4 MiB (for 48 bit virtual addresses) and points to sub maps of 64 KiB.
714	// the page-map is committed on-demand (in 64 KiB parts) (and sub-maps are committed on-demand as well)
715	// one sub page-map = 64 KiB => covers 2^(16-3) * 2^16 = 2^29 = 512 MiB address space
716	// the page-map needs 48-(16+13) = 19 bits => 2^19 sub map pointers = 2^22 bytes = 4 MiB reserved size.
717	#define MI_PAGE_MAP_SUB_SHIFT     (13)
718	#define MI_PAGE_MAP_SUB_COUNT     (MI_ZU(1) << MI_PAGE_MAP_SUB_SHIFT)
719	#define MI_PAGE_MAP_SHIFT         (MI_MAX_VABITS - MI_PAGE_MAP_SUB_SHIFT - MI_ARENA_SLICE_SHIFT)
720	
721	typedef mi_page_t**   mi_submap_t;
722	typedef struct mi_page_map_s {  
723	  _Atomic(size_t)      committed_count;  // currently committed entries
724	  size_t               reserved_size;    // full reserved size (mi_page_map_t + submaps)
725	  mi_memid_t           memid;            // provenance
726	  mi_lock_t            lock;             // used when allocating new submaps
727	  _Atomic(mi_submap_t) submaps[1];
728	} mi_page_map_t;
729	
730	extern mi_decl_hidden _Atomic(mi_page_map_t*) __mi_page_map;
731	
732	static inline size_t _mi_page_map_index(const void* p, size_t* sub_idx) {
733	  const size_t u = (size_t)((uintptr_t)p / MI_ARENA_SLICE_SIZE);
734	  if (sub_idx != NULL) { *sub_idx = u % MI_PAGE_MAP_SUB_COUNT; }
735	  return (u / MI_PAGE_MAP_SUB_COUNT);
736	}
737	
738	static inline mi_page_map_t* _mi_page_map(void) {
739	  return mi_atomic_load_ptr_relaxed(mi_page_map_t,&__mi_page_map);
740	}
741	
742	static inline mi_submap_t _mi_page_map_at(const mi_page_map_t* pmap, size_t idx) {
743	  return mi_atomic_load_ptr_acquire(mi_page_t*, &pmap->submaps[idx]);
744	}
745	
746	static inline mi_page_t* _mi_unchecked_ptr_page(const void* p) {
747	  const mi_page_map_t* pmap = _mi_page_map();
748	  size_t sub_idx;
749	  const size_t idx = _mi_page_map_index(p, &sub_idx);
750	  return _mi_page_map_at(pmap,idx)[sub_idx];  // NULL if p==NULL
751	}
752	
753	static inline mi_page_t* _mi_checked_ptr_page(const void* p) {
754	  const mi_page_map_t* pmap = _mi_page_map();
755	  size_t sub_idx;
756	  const size_t idx = _mi_page_map_index(p, &sub_idx);
757	  const size_t committed_count = mi_atomic_load_relaxed(&pmap->committed_count);    
758	  if mi_unlikely(idx >= committed_count) return NULL;
759	  // #if MI_MIN_VABITS < MI_INTPTR_BITS   // is still invalid if free is called before the pagemap is initialized
760	  // if mi_unlikely(((uintptr_t)p >> MI_MIN_VABITS) != 0) {  
761	  //   const size_t committed_count = mi_atomic_load_relaxed(&pmap->committed_count);      
762	  //   if mi_unlikely(idx >= committed_count) return NULL;
763	  // }   
764	  // #endif
765	  mi_submap_t const sub = _mi_page_map_at(pmap,idx);
766	  if mi_unlikely(sub == NULL) return NULL;
767	  return sub[sub_idx];
768	}
769	
770	#endif
771	
772	#if MI_PAGE_META_IS_ALIGNED
773	// if the page meta data is aligned in front of pages we can find it efficiently
774	// without needing to go through the page map (for valid pointers).
775	static inline mi_page_t* _mi_aligned_ptr_page0(const void* p) {
776	  mi_page_t* const page_metas = (mi_page_t*)_mi_align_down_ptr(p,MI_PAGE_META_ALIGNMENT);
777	  const ptrdiff_t page_idx = ((uint8_t*)p - (uint8_t*)page_metas)/MI_ARENA_SLICE_SIZE;
778	  mi_assert_internal(page_idx >= 0 && page_idx <= MI_PAGE_META_ALIGNED_COUNT);
779	  return &page_metas[page_idx];
780	}
781	
782	static inline mi_page_t* _mi_aligned_ptr_page(const void* p) {
783	  mi_page_t* const page = _mi_aligned_ptr_page0(p);
784	  if mi_unlikely(page==NULL) return NULL;
785	  #if MI_DEBUG
786	    mi_page_t* const cpage = _mi_checked_ptr_page(p);
787	    if mi_unlikely(cpage==NULL) { 
788	      _mi_error_message(EINVAL, "_mi_aligned_ptr_page: invalid pointer: %p\n", p); 
789	      return NULL;
790	    }
791	  #endif
792	  return mi_atomic_load_acquire(&page->self);
793	}
794	#endif
795	
796	static inline mi_page_t* _mi_ptr_page(const void* p) {
797	  mi_assert_internal(p==NULL || mi_is_in_heap_region(p));
798	  #if MI_SECURE || MI_FREE_IS_CHECKED
799	    return _mi_checked_ptr_page(p);
800	  #elif MI_PAGE_META_IS_ALIGNED
801	    return _mi_aligned_ptr_page(p);
802	  #elif MI_DEBUG
803	    return _mi_checked_ptr_page(p);
804	  #else  
805	    return _mi_unchecked_ptr_page(p);
806	  #endif
807	}
