960	// Thread id of thread that owns this page (with flags in the bottom 2 bits)
961	static inline mi_threadid_t mi_page_xthread_id(const mi_page_t* page) {
962	  return mi_atomic_load_relaxed(&((mi_page_t*)page)->xthread_id);
963	}
