970	static inline mi_page_flags_t mi_page_flags(const mi_page_t* page) {
971	  return (mi_page_xthread_id(page) & MI_PAGE_FLAG_MASK);
972	}
973	
974	static inline bool mi_page_flags_set(mi_page_t* page, bool set, mi_page_flags_t newflag) {
975	  mi_page_flags_t old;
976	  if (set) { old = mi_atomic_or_relaxed(&page->xthread_id, newflag); }
977	      else { old = mi_atomic_and_relaxed(&page->xthread_id, ~newflag); }
978	  return ((old & newflag) == newflag);
979	}
