985	static inline void mi_page_set_in_full(mi_page_t* page, bool in_full) {
986	  const bool was_in_full = mi_page_flags_set(page, in_full, MI_PAGE_IN_FULL_QUEUE);
987	  if (was_in_full != in_full) {
988	    // optimize: maintain pages_full_size to avoid visiting the full queue (issue #1220)
989	    mi_theap_t* const theap = page->theap;
990	    mi_assert_internal(theap!=NULL);
991	    if (theap != NULL) {
992	      mi_assert_internal(page->capacity==page->reserved);
993	      const size_t size = page->reserved * mi_page_block_size(page);
994	      if (in_full) { theap->pages_full_size += size; }
995	              else { mi_assert_internal(size <= theap->pages_full_size); theap->pages_full_size -= size; }
996	    }
997	  }
998	}
