1008	static inline void mi_page_set_theap(mi_page_t* page, mi_theap_t* theap) {
1009	  // mi_assert_internal(!mi_page_is_in_full(page));  // can happen when destroying pages on theap_destroy
1010	  page->theap = theap;
1011	  const mi_threadid_t tid = (theap == NULL ? MI_THREADID_ABANDONED : theap->tld->thread_id);
1012	  mi_assert_internal((tid & MI_PAGE_FLAG_MASK) == 0);
1013	
1014	  // we need to use an atomic cas since a concurrent thread may still set the MI_PAGE_HAS_INTERIOR_POINTERS flag (see `alloc_aligned.c`).
1015	  mi_threadid_t xtid_old = mi_page_xthread_id(page);
1016	  mi_threadid_t xtid;
1017	  do {
1018	    xtid = tid | (xtid_old & MI_PAGE_FLAG_MASK);
1019	  } while (!mi_atomic_cas_weak_release(&page->xthread_id, &xtid_old, xtid));
1020	}
