1104	// are there any available blocks?
1105	static inline bool mi_page_has_any_available(const mi_page_t* page) {
1106	  mi_assert_internal(page != NULL && page->reserved > 0);
1107	  return (page->used < page->reserved || (mi_page_thread_free(page) != NULL));
1108	}
1109	
1110	// Owned?
1111	static inline bool mi_page_is_owned(const mi_page_t* page) {
1112	  return mi_tf_is_owned(mi_atomic_load_relaxed(&((mi_page_t*)page)->xthread_free));
1113	}
1114	
1115	// get ownership; returns true if the page was not owned before.
1116	static inline bool mi_page_claim_ownership(mi_page_t* page) {
1117	  const uintptr_t old = mi_atomic_or_acq_rel(&page->xthread_free, (uintptr_t)1);
1118	  return ((old&1)==0);
1119	}
1120	
1121	
1122	/* -------------------------------------------------------------------
1123	  Guarded objects
1124	------------------------------------------------------------------- */
1125	#if MI_GUARDED
1126	// we always align guarded pointers in a block at an offset
1127	// the block `next` field is then used as a tag to distinguish regular offset aligned blocks from guarded ones
1128	#define MI_BLOCK_TAG_ALIGNED   ((mi_encoded_t)(0))
1129	#define MI_BLOCK_TAG_GUARDED   (~MI_BLOCK_TAG_ALIGNED)
1130	#endif
1131	
1132	static inline bool mi_block_ptr_is_guarded(const mi_block_t* block, const void* p) {
1133	#if MI_GUARDED
1134	  const ptrdiff_t offset = (uint8_t*)p - (uint8_t*)block;
1135	  return (offset >= (ptrdiff_t)(sizeof(mi_block_t)) && block->next == MI_BLOCK_TAG_GUARDED);
1136	#else
1137	  MI_UNUSED(block); MI_UNUSED(p);
1138	  return false;
1139	#endif
1140	}
1141	
1142	#if MI_GUARDED
1143	static inline bool mi_theap_malloc_use_guarded(mi_theap_t* theap, size_t size) {
1144	  // this code is written to result in fast assembly as it is on the hot path for allocation
1145	  const size_t count = theap->guarded_sample_count - 1;  // if the rate was 0, this will underflow and count for a long time..
1146	  if mi_likely(count != 0) {
1147	    // no sample
1148	    theap->guarded_sample_count = count;
1149	    return false;
1150	  }
1151	  else {
1152	    // count == 0
1153	    const size_t rate = theap->guarded_sample_rate;
1154	    if (rate == 0) {
1155	      return false; // don't write to an empty theap
1156	    }
1157	    else if (size >= theap->guarded_size_min && size <= theap->guarded_size_max) {
1158	      // use guarded allocation
1159	      theap->guarded_sample_count = rate;  // reset
1160	      return true;
1161	    }
1162	    else {
1163	      // failed size criteria, rewind count
1164	      theap->guarded_sample_count = 1;
1165	      return false;
1166	    }
1167	  }
1168	}
1169	
1170	mi_decl_restrict void* _mi_theap_malloc_guarded(mi_theap_t* theap, size_t size, bool zero, mi_page_t** ppage) mi_attr_noexcept;
1171	#endif
1172	
1173	/* -------------------------------------------------------------------
1174	Encoding/Decoding the free list next pointers
1175	
1176	This is to protect against buffer overflow exploits where the
1177	free list is mutated. Many hardened allocators xor the next pointer `p`
1178	with a secret key `k1`, as `p^k1`. This prevents overwriting with known
1179	values but might be still too weak: if the attacker can guess
1180	the pointer `p` this  can reveal `k1` (since `p^k1^p == k1`).
1181	Moreover, if multiple blocks can be read as well, the attacker can
1182	xor both as `(p1^k1) ^ (p2^k1) == p1^p2` which may reveal a lot
1183	about the pointers (and subsequently `k1`).
1184	
1185	Instead mimalloc uses an extra key `k2` and encodes as `((p^k2)<<<k1)+k1`.
1186	Since these operations are not associative, the above approaches do not
1187	work so well any more even if the `p` can be guesstimated. For example,
1188	for the read case we can subtract two entries to discard the `+k1` term,
1189	but that leads to `((p1^k2)<<<k1) - ((p2^k2)<<<k1)` at best.
1190	We include the left-rotation since xor and addition are otherwise linear
1191	in the lowest bit. Finally, both keys are unique per page which reduces
1192	the re-use of keys by a large factor.
1193	
1194	We also pass a separate `null` value to be used as `NULL` or otherwise
1195	`(k2<<<k1)+k1` would appear (too) often as a sentinel value.
1196	------------------------------------------------------------------- */
1197	
1198	static inline bool mi_is_in_same_page(const void* p, const void* q) {
1199	  mi_page_t* page = _mi_ptr_page(p);
1200	  return mi_page_contains_address(page,q);
1201	  // return (_mi_ptr_page(p) == _mi_ptr_page(q));
1202	}
1203	
1204	static inline void* mi_ptr_decode(const void* null, const mi_encoded_t x, const uintptr_t* keys) {
1205	  const uintptr_t k1 = keys[0];
1206	  #if MI_PAGE_KEY_COUNT==2
1207	  const uintptr_t k2 = keys[1];
1208	  #else
1209	  const uintptr_t k2 = mi_rotr(k1,13);
1210	  #endif
1211	  void* p = (void*)(mi_rotr(x - k1, k1) ^ k2);
1212	  return (p==null ? NULL : p);
1213	}
1214	
1215	static inline mi_encoded_t mi_ptr_encode(const void* null, const void* p, const uintptr_t* keys) {
1216	  const uintptr_t k1 = keys[0];
1217	  #if MI_PAGE_KEY_COUNT==2
1218	  const uintptr_t k2 = keys[1];
1219	  #else
1220	  const uintptr_t k2 = mi_rotr(k1,13);
1221	  #endif
1222	  const uintptr_t x = (uintptr_t)(p==NULL ? null : p);  
1223	  return mi_rotl(x ^ k2, k1) + k1;
1224	}
1225	
1226	static inline uint32_t mi_ptr_encode_canary(const void* null, const void* p, const uintptr_t* keys) {
1227	  const uint32_t x = (uint32_t)(mi_ptr_encode(null,p,keys));
1228	  // make the lowest byte 0 to prevent spurious read overflows which could be a security issue (issue #951)
1229	  // also clear bit 9 which we set only when a block is freed.
1230	  #if MI_BIG_ENDIAN
1231	  return (x & 0x00FFFEFF);
1232	  #else
1233	  return (x & 0xFFFFFE00);
1234	  #endif
1235	}
1236	
1237	static inline uint32_t mi_ptr_encode_canary_freed(void) {
1238	  return (0x00DEAD00);  // set bit 9 so it is different from any valid canary
1239	}
1240	
1241	static inline bool mi_ptr_decode_canary_is_freed(uint32_t canary) {
1242	  return (canary == mi_ptr_encode_canary_freed());
1243	}
1244	
1245	static inline mi_block_t* mi_block_nextx( const void* null, const mi_block_t* block, const uintptr_t* keys ) {
1246	  mi_track_mem_defined(block,sizeof(mi_block_t));
1247	  mi_block_t* next;
1248	  #if MI_ENCODE_FREELIST
1249	  next = (mi_block_t*)mi_ptr_decode(null, block->next, keys);
1250	  #else
1251	  MI_UNUSED(keys); MI_UNUSED(null);
1252	  next = (mi_block_t*)block->next;
1253	  #endif
1254	  mi_track_mem_noaccess(block,sizeof(mi_block_t));
1255	  return next;
1256	}
1257	
1258	static inline void mi_block_set_nextx(const void* null, mi_block_t* block, const mi_block_t* next, const uintptr_t* keys) {
1259	  mi_track_mem_undefined(block,sizeof(mi_block_t));
1260	  #if MI_ENCODE_FREELIST
1261	  block->next = mi_ptr_encode(null, next, keys);
1262	  #else
1263	  MI_UNUSED(keys); MI_UNUSED(null);
1264	  block->next = (mi_encoded_t)next;
1265	  #endif
1266	  mi_track_mem_noaccess(block,sizeof(mi_block_t));
1267	}
1268	
1269	mi_block_t* _mi_block_next_is_corrupted(const mi_page_t* page, const mi_block_t* block, const mi_block_t* next); // in options.c
1270	
1271	static inline mi_block_t* mi_block_next(const mi_page_t* page, const mi_block_t* block) {
1272	  #if MI_ENCODE_FREELIST
1273	  mi_block_t* next = mi_block_nextx(page,block,page->keys);
1274	  // check for free list corruption: is `next` at least in the same page?
1275	  // todo: check if `next` is `page->block_size` aligned?
1276	  if mi_unlikely(next!=NULL && !mi_page_contains_address(page,next)) {
1277	    return _mi_block_next_is_corrupted(page,block,next); // returns NULL
1278	  }
1279	  return next;
1280	  #else
1281	  MI_UNUSED(page);
1282	  return mi_block_nextx(page,block,NULL);
1283	  #endif
1284	}
1285	
1286	static inline void mi_block_set_next(const mi_page_t* page, mi_block_t* block, const mi_block_t* next) {
1287	  #if MI_ENCODE_FREELIST
1288	  mi_block_set_nextx(page,block,next, page->keys);
1289	  #else
1290	  MI_UNUSED(page);
1291	  mi_block_set_nextx(page,block,next,NULL);
1292	  #endif
1293	}
1294	
1295	
1296	
1297	/* -----------------------------------------------------------
1298	  arena blocks
1299	----------------------------------------------------------- */
1300	
1301	// Blocks needed for a given byte size
1302	static inline size_t mi_slice_count_of_size(size_t size) {
1303	  return _mi_divide_up(size, MI_ARENA_SLICE_SIZE);
1304	}
1305	
1306	// Byte size of a number of blocks
1307	static inline size_t mi_size_of_slices(size_t bcount) {
1308	  return (bcount * MI_ARENA_SLICE_SIZE);
1309	}
1310	
1311	
1312	/* -----------------------------------------------------------
1313	  memory id's
1314	----------------------------------------------------------- */
1315	
1316	static inline mi_memid_t _mi_memid_create(mi_memkind_t memkind) {
1317	  mi_memid_t memid;
1318	  _mi_memzero_var(memid);
1319	  memid.memkind = memkind;
1320	  return memid;
1321	}
1322	
1323	static inline mi_memid_t _mi_memid_none(void) {
1324	  return _mi_memid_create(MI_MEM_NONE);
1325	}
1326	
1327	static inline mi_memid_t _mi_memid_create_os(void* base, size_t size, bool committed, bool is_zero, bool is_large) {
1328	  mi_memid_t memid = _mi_memid_create(MI_MEM_OS);
1329	  memid.mem.os.base = base;
1330	  memid.mem.os.size = size;
1331	  memid.initially_committed = committed;
1332	  memid.initially_zero = is_zero;
1333	  memid.is_pinned = is_large;
1334	  return memid;
1335	}
1336	
1337	static inline mi_memid_t _mi_memid_create_static(void* p, size_t size) {
1338	  mi_memid_t memid = _mi_memid_create(MI_MEM_STATIC);
1339	  memid.mem.malloc.base = p;
1340	  memid.mem.malloc.size = size;
1341	  memid.initially_committed = true;
1342	  memid.is_pinned = true;
1343	  return memid;
1344	}
1345	
1346	static inline mi_memid_t _mi_memid_create_malloc(void* p, size_t size, bool iszero) {
1347	  mi_memid_t memid = _mi_memid_create(MI_MEM_MALLOC);
1348	  memid.mem.malloc.base = p;
1349	  memid.mem.malloc.size = size;
1350	  memid.initially_committed = true;
1351	  memid.initially_zero = iszero;
1352	  memid.is_pinned = true;
1353	  return memid;
1354	}
1355	
1356	static inline size_t _mi_memid_size(mi_memid_t memid) {
1357	  if (mi_memid_is_os(memid)) {
1358	    return memid.mem.os.size;
1359	  }
1360	  else if (memid.memkind == MI_MEM_ARENA) {
1361	    return mi_size_of_slices(memid.mem.arena.slice_count);
1362	  }
1363	  else if (memid.memkind == MI_MEM_MALLOC) {
1364	    return memid.mem.malloc.size;
1365	  }
1366	  else {
1367	    mi_assert_internal(mi_memid_needs_no_free(memid));
1368	    return 0;
1369	  }  
1370	}
1371	
1372	// -------------------------------------------------------------------
1373	// Fast "random" shuffle
1374	// -------------------------------------------------------------------
1375	
1376	static inline uintptr_t _mi_random_shuffle(uintptr_t x) {
1377	  if (x==0) { x = 17; }   // ensure we don't get stuck in generating zeros
1378	#if (MI_INTPTR_SIZE>=8)
1379	  // by Sebastiano Vigna, see: <http://xoshiro.di.unimi.it/splitmix64.c>
1380	  x ^= x >> 30;
1381	  x *= 0xbf58476d1ce4e5b9UL;
1382	  x ^= x >> 27;
1383	  x *= 0x94d049bb133111ebUL;
1384	  x ^= x >> 31;
1385	#elif (MI_INTPTR_SIZE==4)
1386	  // by Chris Wellons, see: <https://nullprogram.com/blog/2018/07/31/>
1387	  x ^= x >> 16;
1388	  x *= 0x7feb352dUL;
1389	  x ^= x >> 15;
1390	  x *= 0x846ca68bUL;
1391	  x ^= x >> 16;
1392	#endif
1393	  return x;
1394	}
1395	
1396	
1397	// ---------------------------------------------------------------------------------
1398	// Provide our own `_mi_memcpy/set` for potential performance optimizations.
1399	//
1400	// For now, only on x64/x86 we optimize to `rep movsb/stosb`.
1401	// Generally, we check for "fast short rep movsb/stosb" (FSRM/FSRS) or "fast enhanced rep movsb" (ERMS) support
1402	// (AMD Zen3+ (~2020) or Intel Ice Lake+ (~2017). See also issue #201 and pr #253.
1403	// Todo: we see improvements on win32 but less with glibc; we might want to only enable this on windows.
1404	// ---------------------------------------------------------------------------------
1405	
1406	#if !MI_TRACK_ENABLED && (MI_ARCH_X64 || MI_ARCH_X86) && (defined(_WIN32) || defined(__GNUC__))
1407	
1408	extern mi_decl_hidden size_t _mi_cpu_movsb_max;  // in init.c
1409	extern mi_decl_hidden size_t _mi_cpu_stosb_max;
1410	
1411	static inline void mi_rep_movsb(void* dst, const void* src, size_t n) {
1412	  #if defined(__GNUC__)
1413	  __asm volatile("rep movsb" : "+D"(dst), "+c"(n), "+S"(src) : : "memory");
1414	  #else
1415	  __movsb((unsigned char*)dst, (const unsigned char*)src, n);
1416	  #endif
1417	}
1418	
1419	static inline void mi_rep_stosb(void* dst, uint8_t val, size_t n) {
1420	  #if defined(__GNUC__)
1421	  __asm volatile("rep stosb" : "+D"(dst), "+c"(n) : "a"(val) : "memory");
1422	  #else
1423	  __stosb((unsigned char*)dst, val, n);
1424	  #endif
1425	}
1426	
1427	static inline void _mi_memcpy(void* dst, const void* src, size_t n) {
1428	  if mi_likely(n <= _mi_cpu_movsb_max) {  // has fsrm && n <= 127  (todo: and maybe has erms?)
1429	    mi_rep_movsb(dst, src, n);
1430	  }
1431	  else {
1432	    memcpy(dst, src, n);
1433	  }
1434	}
1435	
1436	static inline void _mi_memset(void* dst, int val, size_t n) {
1437	  if mi_likely(n <= _mi_cpu_stosb_max) {  // has fsrs && n <= 127
1438	    mi_rep_stosb(dst, (uint8_t)val, n);
1439	  }
1440	  else {
1441	    memset(dst, val, n);
1442	  }
1443	}
1444	
1445	#else
1446	
1447	static inline void _mi_memcpy(void* dst, const void* src, size_t n) {
1448	  memcpy(dst, src, n);
1449	}
1450	
1451	static inline void _mi_memset(void* dst, int val, size_t n) {
1452	  memset(dst, val, n);
1453	}
1454	
1455	#endif
1456	
1457	// -------------------------------------------------------------------------------
1458	// The `_mi_memcpy_aligned` can be used if the pointers are machine-word aligned
1459	// This is used for example in `mi_realloc`.
1460	// -------------------------------------------------------------------------------
1461	
1462	#if (defined(__GNUC__) && (__GNUC__ >= 4)) || defined(__clang__)
1463	
1464	// On GCC/CLang we provide a hint that the pointers are word aligned.
1465	static inline void _mi_memcpy_aligned(void* dst, const void* src, size_t n) {
1466	  mi_assert_internal(((uintptr_t)dst % MI_INTPTR_SIZE == 0) && ((uintptr_t)src % MI_INTPTR_SIZE == 0));
1467	  void* adst = __builtin_assume_aligned(dst, MI_INTPTR_SIZE);
1468	  const void* asrc = __builtin_assume_aligned(src, MI_INTPTR_SIZE);
1469	  _mi_memcpy(adst, asrc, n);
1470	}
1471	
1472	static inline void _mi_memset_aligned(void* dst, int val, size_t n) {
1473	  mi_assert_internal((uintptr_t)dst % MI_INTPTR_SIZE == 0);
1474	  void* adst = __builtin_assume_aligned(dst, MI_INTPTR_SIZE);
1475	  _mi_memset(adst, val, n);
1476	}
1477	
1478	#else
1479	
1480	// Default fallback on `_mi_memcpy`
1481	static inline void _mi_memcpy_aligned(void* dst, const void* src, size_t n) {
1482	  mi_assert_internal(((uintptr_t)dst % MI_INTPTR_SIZE == 0) && ((uintptr_t)src % MI_INTPTR_SIZE == 0));
1483	  _mi_memcpy(dst, src, n);
1484	}
1485	
1486	static inline void _mi_memset_aligned(void* dst, int val, size_t n) {
1487	  mi_assert_internal((uintptr_t)dst % MI_INTPTR_SIZE == 0);
1488	  _mi_memset(dst, val, n);
1489	}
1490	
1491	#endif
1492	
1493	static inline void _mi_memzero(void* dst, size_t n) {
1494	  _mi_memset(dst, 0, n);
1495	}
1496	
1497	static inline void _mi_memzero_aligned(void* dst, size_t n) {
1498	  _mi_memset_aligned(dst, 0, n);
1499	}
1500	
1501	
1502	
1503	#endif  // MI_INTERNAL_H
